<script setup>
/* eslint-disable vue/no-bare-strings-in-template */
import { computed, onMounted, reactive, ref } from 'vue';import { goalsAPI } from 'dashboard/api/crm/commercialCycle';import AgentsAPI from 'dashboard/api/agents';import { useAlert } from 'dashboard/composables';
const rows=ref([]);const agents=ref([]);const loading=ref(false);const showForm=ref(false);const saving=ref(false);const form=reactive({user_id:'',period_start:'',period_end:'',target:'0'});const cents=v=>Math.round((Number(String(v).replace(',','.'))||0)*100);const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(v)||0)/100);const total=computed(()=>rows.value.reduce((s,r)=>s+(Number(r.target_cents)||0),0));const load=async()=>{loading.value=true;try{const [r,a]=await Promise.all([goalsAPI.list(),AgentsAPI.get()]);rows.value=r.data||[];agents.value=a.data||[];}finally{loading.value=false;}};const save=async()=>{saving.value=true;try{await goalsAPI.create({goal:{user_id:form.user_id||null,period_start:form.period_start,period_end:form.period_end,target_cents:cents(form.target)}});showForm.value=false;await load();useAlert('Meta criada.');}catch(e){useAlert(e.response?.data?.errors?.join(', ')||'Não foi possível criar a meta.');}finally{saving.value=false;}};onMounted(load);
</script>
<template><div class="h-full overflow-auto bg-n-surface-1 p-4 sm:p-6"><header class="mb-5 flex flex-wrap items-center justify-between gap-3"><div class="flex items-center gap-3"><span class="grid size-11 place-content-center rounded-2xl bg-cyan-50 text-cyan-700"><i class="i-lucide-target size-5" /></span><div><h2 class="text-2xl font-bold">Metas</h2><p class="text-sm text-n-slate-9">Metas individuais e acompanhamento comercial por período.</p></div></div><button class="rounded-xl bg-n-brand px-4 py-2.5 text-sm font-semibold text-white" @click="showForm=true">+ Nova meta</button></header><div class="mb-4 grid gap-3 sm:grid-cols-2"><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Metas cadastradas</p><strong class="text-2xl">{{ rows.length }}</strong></article><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Total de metas</p><strong class="text-xl text-cyan-700">{{ money(total) }}</strong></article></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="row in rows" :key="row.id" class="rounded-2xl border border-n-weak bg-white p-5 shadow-sm"><div class="flex items-start justify-between"><div><p class="text-xs uppercase text-n-slate-9">Meta individual</p><h3 class="mt-1 font-semibold">{{ row.user?.name || 'Equipe' }}</h3></div><span class="rounded-full bg-cyan-50 px-2 py-1 text-xs font-semibold text-cyan-700">{{ row.period_start }} — {{ row.period_end }}</span></div><p class="mt-5 text-xs text-n-slate-9">Objetivo</p><strong class="text-2xl">{{ money(row.target_cents) }}</strong><div class="mt-4 h-2 overflow-hidden rounded-full bg-n-alpha-3"><div class="h-full w-0 rounded-full bg-cyan-600" /></div><p class="mt-2 text-xs text-n-slate-9">O realizado será alimentado pelos Pedidos/Vendas confirmados.</p></article><p v-if="!loading&&!rows.length" class="text-sm text-n-slate-9">Nenhuma meta cadastrada.</p></div><Teleport to="body"><div v-if="showForm" class="fixed inset-0 z-[90] grid place-content-center bg-black/45 p-4" @click.self="showForm=false"><form class="w-full max-w-lg rounded-2xl bg-white p-6" @submit.prevent="save"><h3 class="text-xl font-bold">Nova meta</h3><div class="mt-5 grid gap-3"><label class="text-sm">Vendedor<select v-model="form.user_id" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2"><option value="">Meta da equipe</option><option v-for="agent in agents" :key="agent.id" :value="agent.id">{{ agent.name||agent.email }}</option></select></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Início<input v-model="form.period_start" required type="date" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Fim<input v-model="form.period_end" required type="date" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label></div><label class="text-sm">Meta (R$)<input v-model="form.target" required type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="rounded-lg border border-n-weak px-4 py-2" @click="showForm=false">Cancelar</button><button :disabled="saving" class="rounded-lg bg-n-brand px-4 py-2 font-semibold text-white">Salvar meta</button></div></form></div></Teleport></div></template>
